package com.reqlens.app;
import android.app.*;import android.os.Bundle;import android.util.Base64;import android.view.*;import android.widget.*;import java.net.*;import java.nio.charset.StandardCharsets;
public final class DecoderActivity extends Activity{private EditText in,out;@Override public void onCreate(Bundle b){super.onCreate(b);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(16,16,16,16);in=new EditText(this);in.setHint("Input");in.setMinLines(5);r.addView(in);LinearLayout a=new LinearLayout(this);String[]n={"URL ENCODE","URL DECODE","B64 ENCODE","B64 DECODE"};for(String x:n){Button bt=new Button(this);bt.setText(x);bt.setOnClickListener(v->go(((Button)v).getText().toString()));a.addView(bt,new LinearLayout.LayoutParams(0,50,1));}r.addView(a);out=new EditText(this);out.setHint("Output");out.setMinLines(8);out.setTextIsSelectable(true);r.addView(out);setContentView(r);}private void go(String m){try{String s=in.getText().toString(),z="";if(m.startsWith("URL E"))z=URLEncoder.encode(s,"UTF-8");else if(m.startsWith("URL D"))z=URLDecoder.decode(s,"UTF-8");else if(m.startsWith("B64 E"))z=Base64.encodeToString(s.getBytes(StandardCharsets.UTF_8),Base64.NO_WRAP);else z=new String(Base64.decode(s,Base64.DEFAULT),StandardCharsets.UTF_8);out.setText(z);}catch(Exception e){out.setText("Error: "+e.getMessage());}}}
